import React, { useState, useRef } from "react";
import { Image, Text, View } from "react-native";
import { SkeuoButton } from "./skeuo-button";
import { useSkeuo } from "./theme";
export type PhotoItem = { uri: string; title: string; caption?: string };
export function SkeuoPhotoCarousel({
  items,
  label = "Photo collection",
}: {
  items: PhotoItem[];
  label?: string;
}) {
  const { colors: c } = useSkeuo();
  const [position, setPosition] = useState(0);
  const touch = useRef({x:0,y:0});
  const index = Math.min(position, Math.max(0, items.length - 1));
  const item = items[index];
  if (!item) return <Text style={{ color: c.muted }}>No photos yet.</Text>;
  return (
    <View accessibilityLabel={label} style={{ gap: 20, paddingTop: 16 }}>
      <View onTouchStart={event => { touch.current = {x:event.nativeEvent.pageX,y:event.nativeEvent.pageY}; }} onTouchEnd={event => { const dx=event.nativeEvent.pageX-touch.current.x; const dy=event.nativeEvent.pageY-touch.current.y; if(Math.abs(dx)>40 && Math.abs(dx)>Math.abs(dy)) setPosition(Math.max(0,Math.min(items.length-1,index+(dx<0?1:-1)))); }} style={{ height: 244, marginHorizontal: 20 }}>
        {[-7, 5].map((rotation, i) => (
          <View
            key={rotation}
            style={{
              position: "absolute",
              inset: 0,
              backgroundColor: c.surface,
              borderWidth: 1,
              borderColor: c.edge,
              borderRadius: 3,
              transform: [{ rotate: `${rotation}deg` }],
              margin: 6 + i * 2,
            }}
          />
        ))}
        <View
          style={{
            flex: 1,
            padding: 10,
            paddingBottom: 16,
            backgroundColor: c.raised,
            borderWidth: 1,
            borderColor: c.edge,
            borderBottomWidth: 3,
            gap: 8,
          }}
        >
          <Image
            source={{ uri: item.uri }}
            accessibilityLabel={item.title}
            alt={item.title}
            resizeMode="cover"
            style={{ flex: 1, backgroundColor: c.well }}
          />
          <Text style={{ color: c.ink, fontSize: 15, fontWeight: "600" }}>
            {item.title}
          </Text>
        </View>
      </View>
      <View
        style={{
          flexDirection: "row",
          justifyContent: "space-between",
          alignItems: "center",
          gap: 12,
        }}
      >
        <SkeuoButton
          accessibilityLabel="Previous photo"
          disabled={index === 0}
          onPress={() => setPosition(index - 1)}
        >
          ‹
        </SkeuoButton>
        <Text
          accessibilityLiveRegion="polite"
          style={{ color: c.muted, fontSize: 12 }}
        >
          {index + 1} / {items.length}
        </Text>
        <SkeuoButton
          accessibilityLabel="Next photo"
          disabled={index === items.length - 1}
          onPress={() => setPosition(index + 1)}
        >
          ›
        </SkeuoButton>
      </View>
      {item.caption && (
        <Text style={{ color: c.muted, fontSize: 13, lineHeight: 20 }}>
          {item.caption}
        </Text>
      )}
    </View>
  );
}

import { StyleSheet } from "react-native";
import React from "react";
import { Button } from "@/components/ui/button";
import { Text } from "@/components/ui/text";
import { LinearGradient } from "expo-linear-gradient";
import { useSkeuo, useFeedback } from "./theme";
import { styles } from "./styles";
import type { ButtonProps } from "./types";
export function SkeuoButton({
  children,
  onPress,
  disabled = false,
  variant = "default",
  accessibilityLabel,
}: ButtonProps) {
  const { colors } = useSkeuo();
  const feedback = useFeedback();
  const accent = variant === "accent";
  const [focused, setFocused] = React.useState(false);
  const [pressed, setPressed] = React.useState(false);
  return (
    <Button
      variant="ghost"
      className="p-0 h-auto"
      onPressIn={() => setPressed(true)}
      onPressOut={() => setPressed(false)}
      onFocus={() => setFocused(true)}
      onBlur={() => setFocused(false)}
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel}
      accessibilityState={{ disabled }}
      disabled={disabled}
      onPress={() => {
        feedback();
        onPress();
      }}
      style={StyleSheet.flatten([
        styles.button,
        {
          opacity: disabled ? 0.45 : 1,
          borderColor: focused ? colors.accent : colors.edge,
          backgroundColor: colors.base,
          borderBottomWidth: pressed ? 1 : 4,
          transform: [{ translateY: pressed ? 3 : 0 }],
        },
      ])}
    >
      <LinearGradient
        colors={
          accent
            ? [colors.accent, colors.accent]
            : [colors.raised, colors.surface]
        }
        style={[styles.face, { alignSelf: "stretch", flex: 1 }]}
      >
        {typeof children === "string" ? (
          <Text
            style={{
              color: accent ? colors.accentInk : colors.ink,
              fontSize: 16,
              fontWeight: "600",
              textAlign: "center",
            }}
          >
            {children}
          </Text>
        ) : (
          children
        )}
      </LinearGradient>
    </Button>
  );
}

import React, { createContext, useContext } from "react";
import { useColorScheme } from "nativewind";
import * as Haptics from "expo-haptics";

export const themes = {
  light: {
    background: "#ffffff",
    surface: "#f5f5f2",
    raised: "#fafaf8",
    well: "#e9e9e5",
    edge: "#d1d1cb",
    base: "#d9d9d3",
    ink: "#202020",
    muted: "#686863",
    accent: "#365e50",
    accentInk: "#ffffff",
  },
  dark: {
    background: "#000000",
    surface: "#191919",
    raised: "#252525",
    well: "#111111",
    edge: "#3b3b39",
    base: "#080808",
    ink: "#efefeb",
    muted: "#aaaAA5",
    accent: "#9ab5a6",
    accentInk: "#14251c",
  },
};
type ThemeState = { colors: typeof themes.light; dark: boolean; haptics: boolean; onSound?: () => void };
const Context = createContext<ThemeState | null>(null);
export function SkeuoProvider({
  children,
  appearance = "system",
  haptics = false,
  onSound,
  colors: overrides,
}: {
  children: React.ReactNode;
  appearance?: "light" | "dark" | "system";
  haptics?: boolean;
  onSound?: () => void;
  colors?: Partial<typeof themes.light>;
}) {
  const { colorScheme: system } = useColorScheme();
  const dark = (appearance === "system" ? system : appearance) === "dark";
  return (
    <Context.Provider
      value={{
        colors: { ...(dark ? themes.dark : themes.light), ...overrides },
        dark,
        haptics,
        onSound,
      }}
    >
      {children}
    </Context.Provider>
  );
}
export function useSkeuo(): ThemeState {
  const context = useContext(Context);
  const { colorScheme } = useColorScheme();
  return context ?? { colors: colorScheme === "dark" ? themes.dark : themes.light, dark: colorScheme === "dark", haptics: false };
}
export function useFeedback() {
  const { haptics, onSound } = useSkeuo();
  return () => {
    onSound?.();
    if (haptics) void Haptics.selectionAsync().catch(() => {});
  };
}

import React from "react";
export type ButtonProps = {
  children: React.ReactNode;
  onPress: () => void;
  disabled?: boolean;
  variant?: "default" | "accent";
  accessibilityLabel?: string;
};
export type ToggleProps = {
  label: string;
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
  disabled?: boolean;
};
export type OptionsProps = {
  label: string;
  value: string;
  onValueChange: (value: string) => void;
  options: { label: string; value: string; disabled?: boolean }[];
};
export type OverlayProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  children: React.ReactNode;
};
